/* Halcyon Threshold - Stylesheet */

/* CSS Custom Properties */
:root {
    --color-bg: #0a0a0f;
    --color-bg-elevated: #11111a;
    --color-bg-card: #161622;
    --color-fg: #f0f0f5;
    --color-fg-muted: #888899;
    --color-accent: #00d4aa;
    --color-accent-dim: #00b894;
    --color-border: #2a2a3a;
    --color-border-light: #3a3a4a;

    --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

    --space-xs: 0.5rem;
    --space-sm: 1rem;
    --space-md: 1.5rem;
    --space-lg: 2rem;
    --space-xl: 3rem;
    --space-2xl: 4rem;
    --space-3xl: 6rem;

    --container-max: 1100px;
    --container-padding: 1.5rem;

    --radius-sm: 6px;
    --radius-md: 10px;
    --radius-lg: 16px;

    --transition-fast: 150ms ease;
    --transition-base: 250ms ease;
}

/* Reset & Base */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-sans);
    background-color: var(--color-bg);
    color: var(--color-fg);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

a {
    color: var(--color-accent);
    text-decoration: none;
    transition: color var(--transition-fast);
}

a:hover {
    color: var(--color-accent-dim);
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

ul {
    list-style: none;
}

/* Container */
.container {
    max-width: var(--container-max);
    margin: 0 auto;
    padding: 0 var(--container-padding);
}

/* Header */
.header {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 100;
    background: rgba(10, 10, 15, 0.85);
    backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--color-border);
}

.header .container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 72px;
}

.logo {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-weight: 600;
    font-size: 1.125rem;
    color: var(--color-fg);
}

.logo:hover {
    color: var(--color-fg);
}

.logo-mark {
    width: 36px;
    height: 36px;
    background: linear-gradient(135deg, var(--color-accent), #00b8d4);
    border-radius: var(--radius-md);
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 0.875rem;
    color: var(--color-bg);
    letter-spacing: -0.02em;
}

.nav {
    display: flex;
    gap: 2rem;
}

.nav-link {
    color: var(--color-fg-muted);
    font-weight: 500;
    font-size: 0.9375rem;
    padding: 0.5rem 0;
    position: relative;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--color-accent);
    transition: width var(--transition-base);
}

.nav-link:hover {
    color: var(--color-fg);
}

.nav-link:hover::after {
    width: 100%;
}

/* Hero Section */
.hero {
    min-height: 100vh;
    display: flex;
    align-items: center;
    padding-top: 72px;
    position: relative;
    overflow: hidden;
}

.hero::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: 
        radial-gradient(ellipse 80% 50% at 50% -20%, rgba(0, 212, 170, 0.08) 0%, transparent 70%),
        radial-gradient(ellipse 60% 40% at 80% 100%, rgba(0, 184, 212, 0.05) 0%, transparent 60%);
    pointer-events: none;
}

.hero-content {
    position: relative;
    text-align: center;
    max-width: 800px;
    margin: 0 auto;
}

.hero-title {
    font-size: clamp(2.5rem, 6vw, 4.5rem);
    font-weight: 700;
    line-height: 1.1;
    letter-spacing: -0.03em;
    margin-bottom: var(--space-lg);
}

.hero-accent {
    color: var(--color-accent);
    background: linear-gradient(135deg, var(--color-accent), #00b8d4);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.hero-subtitle {
    font-size: clamp(1.125rem, 2.5vw, 1.5rem);
    color: var(--color-fg-muted);
    font-weight: 400;
    margin-bottom: var(--space-xl);
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

.hero-badges {
    display: flex;
    flex-wrap: wrap;
    gap: 0.75rem;
    justify-content: center;
}

.badge {
    padding: 0.5rem 1rem;
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-radius: 100px;
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--color-fg-muted);
    transition: all var(--transition-fast);
}

.badge:hover {
    border-color: var(--color-accent);
    color: var(--color-accent);
}

/* Section Styles */
section {
    padding: var(--space-3xl) 0;
}

.section-title {
    font-size: clamp(1.75rem, 3.5vw, 2.5rem);
    font-weight: 700;
    text-align: center;
    margin-bottom: var(--space-2xl);
    letter-spacing: -0.02em;
}

/* Mission Section */
.mission-section {
    background: var(--color-bg-elevated);
}

.mission-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: var(--space-lg);
}

.mission-card {
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    padding: var(--space-xl);
    transition: all var(--transition-base);
}

.mission-card:hover {
    border-color: var(--color-border-light);
    transform: translateY(-4px);
    box-shadow: 0 20px 40px -20px rgba(0, 0, 0, 0.4);
}

.mission-icon {
    font-size: 2.5rem;
    margin-bottom: var(--space-md);
    line-height: 1;
}

.mission-card h3 {
    font-size: 1.25rem;
    font-weight: 600;
    margin-bottom: var(--space-sm);
}

.mission-card p {
    color: var(--color-fg-muted);
    font-size: 0.9375rem;
    line-height: 1.7;
}

/* Work Section */
.work-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: var(--space-lg);
}

.work-card {
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    padding: var(--space-xl);
    display: flex;
    flex-direction: column;
    transition: all var(--transition-base);
}

.work-card:hover {
    border-color: var(--color-accent);
    box-shadow: 0 20px 40px -20px rgba(0, 212, 170, 0.15);
}

.work-tag {
    display: inline-block;
    padding: 0.25rem 0.75rem;
    background: rgba(0, 212, 170, 0.1);
    color: var(--color-accent);
    border-radius: 100px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    width: fit-content;
    margin-bottom: var(--space-md);
}

.work-card h3 {
    font-size: 1.25rem;
    font-weight: 600;
    margin-bottom: var(--space-sm);
    flex-grow: 1;
}

.work-card p {
    color: var(--color-fg-muted);
    font-size: 0.9375rem;
    line-height: 1.7;
    margin-bottom: var(--space-lg);
}

.work-link {
    font-weight: 500;
    font-size: 0.9375rem;
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
}

.work-link::after {
    content: '→';
    transition: transform var(--transition-fast);
}

.work-link:hover::after {
    transform: translateX(4px);
}

/* Resources Section */
.resources-section {
    background: var(--color-bg-elevated);
}

.resources-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--space-lg);
}

.resource-category h3 {
    font-size: 1.125rem;
    font-weight: 600;
    margin-bottom: var(--space-md);
    padding-bottom: var(--space-sm);
    border-bottom: 1px solid var(--color-border);
}

.resource-list li {
    margin-bottom: var(--space-sm);
}

.resource-list a {
    color: var(--color-fg);
    font-size: 0.9375rem;
    display: inline-block;
    padding: 0.375rem 0;
    transition: color var(--transition-fast);
}

.resource-list a:hover {
    color: var(--color-accent);
}

/* Principles Section */
.principles-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: var(--space-lg);
}

.principle {
    padding: var(--space-lg);
}

.principle h4 {
    font-size: 1.125rem;
    font-weight: 600;
    margin-bottom: var(--space-sm);
    color: var(--color-accent);
}

.principle p {
    color: var(--color-fg-muted);
    font-size: 0.9375rem;
    line-height: 1.7;
}

/* Contact Section */
.contact-section {
    background: var(--color-bg-elevated);
    text-align: center;
}

.contact-content {
    max-width: 600px;
    margin: 0 auto;
}

.contact-content > p {
    color: var(--color-fg-muted);
    margin-bottom: var(--space-lg);
    font-size: 1.0625rem;
}

.contact-email {
    display: inline-block;
    font-size: 1.25rem;
    font-weight: 500;
    color: var(--color-fg);
    margin-bottom: var(--space-md);
    padding: 0.75rem 1.5rem;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    transition: all var(--transition-base);
}

.contact-email:hover {
    border-color: var(--color-accent);
    color: var(--color-accent);
    background: rgba(0, 212, 170, 0.05);
}

.contact-note {
    color: var(--color-fg-muted);
    font-size: 0.875rem;
}

/* Footer */
.footer {
    background: var(--color-bg);
    border-top: 1px solid var(--color-border);
    padding: var(--space-xl) 0;
    text-align: center;
}

.footer p {
    color: var(--color-fg-muted);
    font-size: 0.875rem;
}

.footer-note {
    margin-top: var(--space-xs);
    font-size: 0.8125rem;
}

/* Responsive */
@media (max-width: 768px) {
    .nav {
        display: none;
    }

    .hero {
        padding-top: 100px;
    }

    .section-title {
        margin-bottom: var(--space-xl);
    }

    section {
        padding: var(--space-2xl) 0;
    }

    .mission-grid,
    .work-grid,
    .resources-grid,
    .principles-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 480px) {
    :root {
        --container-padding: 1rem;
    }

    .hero-title {
        font-size: 2.25rem;
    }

    .hero-badges {
        flex-direction: column;
        align-items: center;
    }

    .badge {
        width: 100%;
        max-width: 280px;
        text-align: center;
    }
}

/* Focus styles for accessibility */
:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* Selection */
::selection {
    background: rgba(0, 212, 170, 0.3);
    color: var(--color-fg);
}

